INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4657445, 671918, 89341, '<td valign="top">I can only assume you are going for the brown maybe? The image needs to be bigger.</td>', 'I can only assume you are going for the brown maybe? The image needs to be bigger.', '2008-04-24 16:35:43.000000', NULL, 1),
(4657618, 671964, 85310, '<td valign="top">I quite like the clean simplicity of this image. The glare from the lighting on the top of the lighting element and on parts of the arm is maybe JUST a little bit bright, but otherwise, well done.</td>', 'I quite like the clean simplicity of this image. The glare from the lighting on the top of the lighting element and on parts of the arm is maybe JUST a little bit bright, but otherwise, well done.', '2008-04-24 19:18:34.000000', NULL, 1),
(4657619, 671382, 85310, '<td valign="top">Very nice abstract image. I quite like the range of blue tones and shapes in this image.</td>', 'Very nice abstract image. I quite like the range of blue tones and shapes in this image.', '2008-04-24 19:20:42.000000', NULL, 1),
(4657622, 671685, 85310, '<td valign="top">Nice, symmetrical sunset picture.</td>', 'Nice, symmetrical sunset picture.', '2008-04-24 19:21:48.000000', NULL, 1),
(4657628, 671028, 85310, '<td valign="top">Very nice range of saturated colours in this image. I might try cropping out the edge of the building (?) / differently coloured panels at the left of the image.</td>', 'Very nice range of saturated colours in this image. I might try cropping out the edge of the building (?) / differently coloured panels at the left of the image.', '2008-04-24 19:25:06.000000', NULL, 1),
(4657630, 671016, 85310, '<td valign="top">A lot of interesting texture and atmosphere in this picture. Ironically, I can''t decide whether the two cups add (as an interesting human touch) or detract (seeming out of character relative to the remainder of the image) from the picture.</td>', 'A lot of interesting texture and atmosphere in this picture. Ironically, I can''t decide whether the two cups add (as an interesting human touch) or detract (seeming out of character relative to the remainder of the image) from the picture.', '2008-04-24 19:27:48.000000', NULL, 1),
(4657635, 671398, 85310, '<td valign="top">You have an interesting assortment of colours and shapes here, but my anal-retentive side is distracted by the slight misalignment of some of the items (the hearts, for example.)</td>', 'You have an interesting assortment of colours and shapes here, but my anal-retentive side is distracted by the slight misalignment of some of the items (the hearts, for example.)', '2008-04-24 19:31:29.000000', NULL, 1),
(4657640, 672120, 85310, '<td valign="top">There is a nice nostalgic feel to this image.</td>', 'There is a nice nostalgic feel to this image.', '2008-04-24 19:32:19.000000', NULL, 1),
(4657645, 671918, 85310, '<td valign="top">Your image seems unnecessarily small, which makes it hard to see the detail / texture/ etc. It is hard to appreciate your vision with the small version you have submitted.</td>', 'Your image seems unnecessarily small, which makes it hard to see the detail / texture/ etc. It is hard to appreciate your vision with the small version you have submitted.', '2008-04-24 19:36:36.000000', NULL, 1),
(4657650, 671959, 85310, '<td valign="top">You have managed to capture some interesting texture on the clothespins, but the centred composition does not work for me. <br/> <br/>I''m also curious about your titleare you referring to the P=NP problem in computer science? Or am I just revealing how much of a geek I am?</td>', 'You have managed to capture some interesting texture on the clothespins, but the centred composition does not work for me.  I''m also curious about your titleare you referring to the P=NP problem in computer science? Or am I just revealing how much of a geek I am?', '2008-04-24 19:40:35.000000', NULL, 1),
(4657743, 671777, 89341, '<td valign="top">The colours are good but the background is a little too busy for my liking. Maybe a wider aperture or standing further away with more zoom would blur the background more to isolate the flower.</td>', 'The colours are good but the background is a little too busy for my liking. Maybe a wider aperture or standing further away with more zoom would blur the background more to isolate the flower.', '2008-04-24 20:24:03.000000', NULL, 1),
(4657744, 672182, 89341, '<td valign="top">The composition is good but the image is lacking a bit of clarity</td>', 'The composition is good but the image is lacking a bit of clarity', '2008-04-24 20:24:05.000000', NULL, 1),
(4657745, 671767, 89341, '<td valign="top">It''s all a little to grey for my liking</td>', 'It''s all a little to grey for my liking', '2008-04-24 20:24:37.000000', NULL, 1),
(4657746, 672105, 89341, '<td valign="top">not quite sure how this is even, but never mind. Composition is good, isolation of the flower works well but the flower is not that interesting IMHO</td>', 'not quite sure how this is even, but never mind. Composition is good, isolation of the flower works well but the flower is not that interesting IMHO', '2008-04-24 20:24:40.000000', NULL, 1),
