(4659129, 671367, 91496, '<td valign="top">Middle vase may detract more than it helps.  Nice effect.</td>', 'Middle vase may detract more than it helps.  Nice effect.', '2008-04-25 13:29:42.000000', NULL, 1),
(4659143, 672125, 91496, '<td valign="top">Having all 3 digits "even" would have been cool.  Nice contrast with all the wires/wood.</td>', 'Having all 3 digits "even" would have been cool.  Nice contrast with all the wires/wood.', '2008-04-25 13:39:02.000000', NULL, 1),
(4659149, 671373, 91496, '<td valign="top">I like the concept and it is a nice photo.  However, the pool player in me keeps thinking "there are 15 balls and 15 is not a even number".  I like the inverted cues -- it really frames it well.</td>', 'I like the concept and it is a nice photo.  However, the pool player in me keeps thinking "there are 15 balls and 15 is not a even number".  I like the inverted cues -- it really frames it well.', '2008-04-25 13:41:50.000000', NULL, 1),
(4659156, 671730, 91496, '<td valign="top">Since all 4 stages are the main subject, having a wider DOF which includes all of them may give more impact</td>', 'Since all 4 stages are the main subject, having a wider DOF which includes all of them may give more impact', '2008-04-25 13:45:11.000000', NULL, 1),
