(4659414, 671373, 80458, '<td valign="top">actually your image looks a little tilted, but i''m not detracting that from your score. I like that you are only showing the even #''d balls, but you should''ve put them in numerical order!!!</td>', 'actually your image looks a little tilted, but i''m not detracting that from your score. I like that you are only showing the even #''d balls, but you should''ve put them in numerical order!!!', '2008-04-25 17:07:27.000000', NULL, 1),
(4659415, 671059, 80458, '<td valign="top">something looks strange about the cow on the right, like his head is half-missing.</td>', 'something looks strange about the cow on the right, like his head is half-missing.', '2008-04-25 17:07:55.000000', NULL, 1),
(4659420, 671294, 80458, '<td valign="top">Because you have those two birds that are alone, I dont think this meets the challenge all that well. I think you should''ve cropped it at the bottom up to the 4th row of pigeons and entered this into the "Odds" contest.</td>', 'Because you have those two birds that are alone, I dont think this meets the challenge all that well. I think you should''ve cropped it at the bottom up to the 4th row of pigeons and entered this into the "Odds" contest.', '2008-04-25 17:10:03.000000', NULL, 1),
(4659423, 671274, 80458, '<td valign="top">are these meatballs?<br/> <br/>What is that yellow clump on the one on the left?</td>', 'are these meatballs? What is that yellow clump on the one on the left?', '2008-04-25 17:10:48.000000', NULL, 1),
(4659426, 671674, 80458, '<td valign="top">i think your photograph is technically sound, but honestly, I dont think it meets the challenge all that well. The challenge was to show evenness and I personally dont think it comes off in this image that well. I know that they''re all the same and they look alike, but maybe aligning them would come off a bit stronger.</td>', 'i think your photograph is technically sound, but honestly, I dont think it meets the challenge all that well. The challenge was to show evenness and I personally dont think it comes off in this image that well. I know that they''re all the same and they look alike, but maybe aligning them would come off a bit stronger.', '2008-04-25 17:12:16.000000', NULL, 1),
(4659428, 672019, 80458, '<td valign="top">perhaps my favorite so far! 10!</td>', 'perhaps my favorite so far! 10!', '2008-04-25 17:12:49.000000', NULL, 1),
(4659430, 670417, 80458, '<td valign="top">Go Phillies!</td>', 'Go Phillies!', '2008-04-25 17:13:05.000000', NULL, 1),
(4659431, 672036, 80458, '<td valign="top">This probably would''ve been better for the odds competition! Maybe you should''ve cropped it to make them all even. The dirt in the front is distracting from a truly beautiful image.</td>', 'This probably would''ve been better for the odds competition! Maybe you should''ve cropped it to make them all even. The dirt in the front is distracting from a truly beautiful image.', '2008-04-25 17:13:57.000000', NULL, 1),
(4659432, 671914, 80458, '<td valign="top">I think composing them in the same manner would''ve made a stronger image.</td>', 'I think composing them in the same manner would''ve made a stronger image.', '2008-04-25 17:14:17.000000', NULL, 1),
(4659434, 670788, 80458, '<td valign="top">beautiful. great processing and composition.</td>', 'beautiful. great processing and composition.', '2008-04-25 17:14:41.000000', NULL, 1),
(4659438, 672102, 80458, '<td valign="top">The symmetry, in my opinion, is lost with your background. The background should probably have been broken up equally into four quadrants so that it really brings out that beautiful flower!</td>', 'The symmetry, in my opinion, is lost with your background. The background should probably have been broken up equally into four quadrants so that it really brings out that beautiful flower!', '2008-04-25 17:15:47.000000', NULL, 1),
(4659439, 671928, 80458, '<td valign="top">I almost think this one would do better in the "odds" challenge.</td>', 'I almost think this one would do better in the "odds" challenge.', '2008-04-25 17:16:11.000000', NULL, 1),
(4659440, 672178, 80458, '<td valign="top">i''m not really seeing the "four eyes"?</td>', 'i''m not really seeing the "four eyes"?', '2008-04-25 17:16:33.000000', NULL, 1);
