(4660886, 670351, 55117, '<td valign="top">Like the colors. Would have appreciated either a greater OR more shallow depth of field. The building in the back takes up so much of the frame that it either needs to be lost in the bokeh or tack sharp. As it is, it just likes moderately out of focus, which makes the whole shot look sloppy.</td>', 'Like the colors. Would have appreciated either a greater OR more shallow depth of field. The building in the back takes up so much of the frame that it either needs to be lost in the bokeh or tack sharp. As it is, it just likes moderately out of focus, which makes the whole shot look sloppy.', '2008-04-27 10:49:54.000000', NULL, 1),
(4660887, 671256, 55117, '<td valign="top">Flowers. Again. Tres chic.</td>', 'Flowers. Again. Tres chic.', '2008-04-27 10:50:05.000000', NULL, 1),
(4660889, 672125, 55117, '<td valign="top">What even makes this seem like a good submission? How do you look at this and think "Man, everyone will love this picture of a sign on some wood"?</td>', 'What even makes this seem like a good submission? How do you look at this and think "Man, everyone will love this picture of a sign on some wood"?', '2008-04-27 10:50:40.000000', NULL, 1),
(4660890, 671974, 55117, '<td valign="top">And yet, they don''t work at all.</td>', 'And yet, they don''t work at all.', '2008-04-27 10:50:57.000000', NULL, 1),
(4660891, 671685, 55117, '<td valign="top">Beautiful, but too soft.</td>', 'Beautiful, but too soft.', '2008-04-27 10:51:15.000000', NULL, 1),
(4660892, 671268, 55117, '<td valign="top">I''m ready for this brand of post-processing to fall completely out of style.</td>', 'I''m ready for this brand of post-processing to fall completely out of style.', '2008-04-27 10:52:05.000000', NULL, 1),
(4660893, 672102, 55117, '<td valign="top">Hey....at least it''s a somewhat creative take on the standard flower macro. Points for that.</td>', 'Hey....at least it''s a somewhat creative take on the standard flower macro. Points for that.', '2008-04-27 10:52:47.000000', NULL, 1),
(4660894, 671796, 55117, '<td valign="top">Good action, boring composition.</td>', 'Good action, boring composition.', '2008-04-27 10:53:07.000000', NULL, 1),
(4660895, 671731, 55117, '<td valign="top">Looks like a graphic design piece. A little generic, to be honest.</td>', 'Looks like a graphic design piece. A little generic, to be honest.', '2008-04-27 10:54:02.000000', NULL, 1),
(4660896, 670969, 55117, '<td valign="top">Enough of these shots, please. Everyone has done them now. They aren''t novel anymore. Just stop.</td>', 'Enough of these shots, please. Everyone has done them now. They aren''t novel anymore. Just stop.', '2008-04-27 10:54:37.000000', NULL, 1),
(4660897, 672030, 55117, '<td valign="top">Love the depth of field.</td>', 'Love the depth of field.', '2008-04-27 10:54:49.000000', NULL, 1),
(4660898, 671632, 55117, '<td valign="top">Boring.</td>', 'Boring.', '2008-04-27 10:54:56.000000', NULL, 1),
(4660899, 670417, 55117, '<td valign="top">Terribly oversaturated and soft.</td>', 'Terribly oversaturated and soft.', '2008-04-27 10:55:09.000000', NULL, 1),
(4660903, 671996, 55117, '<td valign="top">Could have been promising, but the execution is kind of boring. Had the lighting been more uniform throughout, this would look better (for example, the top and bottom clearly suffer from vignetting that takes away from the symmetry of the shot).</td>', 'Could have been promising, but the execution is kind of boring. Had the lighting been more uniform throughout, this would look better (for example, the top and bottom clearly suffer from vignetting that takes away from the symmetry of the shot).', '2008-04-27 10:56:30.000000', NULL, 1),
(4660904, 671767, 55117, '<td valign="top">Dumb.</td>', 'Dumb.', '2008-04-27 10:56:37.000000', NULL, 1),
(4660905, 670568, 55117, '<td valign="top">Too soft and too overdone.</td>', 'Too soft and too overdone.', '2008-04-27 10:56:47.000000', NULL, 1),
(4660906, 671891, 55117, '<td valign="top">FLOWERS! I''ve never seen this before!</td>', 'FLOWERS! I''ve never seen this before!', '2008-04-27 10:57:05.000000', NULL, 1),
