(4660908, 671367, 55117, '<td valign="top">Although it''s an overdone concept, this would have been pretty good provided you didn''t have that distracting dark area at the top left.</td>', 'Although it''s an overdone concept, this would have been pretty good provided you didn''t have that distracting dark area at the top left.', '2008-04-27 10:58:29.000000', NULL, 1),
(4660910, 672133, 55117, '<td valign="top">Beautiful. Nothing new, but well executed.</td>', 'Beautiful. Nothing new, but well executed.', '2008-04-27 10:59:08.000000', NULL, 1),
