(4661214, 670969, 4517, '<td valign="top">Been done a million times but rarely this well. Nice colours and perfect drops.9</td>', 'Been done a million times but rarely this well. Nice colours and perfect drops.9', '2008-04-27 15:25:54.000000', NULL, 1),
