(4664183, 671785, 88825, '<td valign="top">I think that the yellow border really helps to make this a beautiful photo. Nice job.</td>', 'I think that the yellow border really helps to make this a beautiful photo. Nice job.', '2008-04-29 00:38:08.000000', NULL, 1),
(4664266, 671830, 89940, '<td valign="top">The lighting is a little harsh and very flat. This photo would look a lot better with a little side soft lighting to get rid of the hard shadows under the chins. The faces are also a little OOF.</td>', 'The lighting is a little harsh and very flat. This photo would look a lot better with a little side soft lighting to get rid of the hard shadows under the chins. The faces are also a little OOF.', '2008-04-29 02:04:00.000000', NULL, 1),
(4664267, 671811, 89940, '<td valign="top">This looks snapshot-ish. It might look a little better with a tighter crop but even then since you are really only seeing one face full on and a little side view on 2 others I''m not sure it would make it more interesting.</td>', 'This looks snapshot-ish. It might look a little better with a tighter crop but even then since you are really only seeing one face full on and a little side view on 2 others I''m not sure it would make it more interesting.', '2008-04-29 02:06:28.000000', NULL, 1),
