(4665830, 671367, 73452, '<td valign="top">very cool composition, but i dont really get the vase in the background</td>', 'very cool composition, but i dont really get the vase in the background', '2008-04-29 21:15:44.000000', NULL, 1),
(4665836, 670971, 73452, '<td valign="top">too much negative space on the lower part of the photo, and i think a sharpen would have helped.  great night shot on the other hand!</td>', 'too much negative space on the lower part of the photo, and i think a sharpen would have helped.  great night shot on the other hand!', '2008-04-29 21:17:29.000000', NULL, 1),
(4665838, 672152, 73452, '<td valign="top">beautiful cat, but i would have taken the collar off.</td>', 'beautiful cat, but i would have taken the collar off.', '2008-04-29 21:18:51.000000', NULL, 1),
(4665840, 671753, 85310, '<td valign="top">This seems too "snapshot" like to me. The focus is not sharp and the background is distracting, especially the two lines that run your your son''s head. Using a shallower depth of field might help by rendering the background blurrier.</td>', 'This seems too "snapshot" like to me. The focus is not sharp and the background is distracting, especially the two lines that run your your son''s head. Using a shallower depth of field might help by rendering the background blurrier.', '2008-04-29 21:19:39.000000', NULL, 1),
