INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4665874, 671964, 73452, '<td valign="top">creative idea! It took me a minute to figure out the meaning along with the title, but now i do.  good job.</td>', 'creative idea! It took me a minute to figure out the meaning along with the title, but now i do.  good job.', '2008-04-29 21:29:13.000000', NULL, 1),
(4665875, 671978, 83313, '<td valign="top">Overall, a good effort with  lots of visual appeal. Lots of grainy nose visible, though. Some noise removal in PP, or shooting at a lower ISO could have helped. Keep an eye on your JPEG compression settings as well, the allowed size is 150k, and your file size of 95k indicates more compression than was needed. Always use the least amount of compression you can get away with and still slip under the file size limit.</td>', 'Overall, a good effort with  lots of visual appeal. Lots of grainy nose visible, though. Some noise removal in PP, or shooting at a lower ISO could have helped. Keep an eye on your JPEG compression settings as well, the allowed size is 150k, and your file size of 95k indicates more compression than was needed. Always use the least amount of compression you can get away with and still slip under the file size limit.', '2008-04-29 21:29:19.000000', NULL, 1),
(4665876, 671834, 73452, '<td valign="top">beautiful, i love the purple against the yellow fields.</td>', 'beautiful, i love the purple against the yellow fields.', '2008-04-29 21:29:38.000000', NULL, 1),
(4665877, 671615, 85310, '<td valign="top">This is a little bit too "snapshot-like" for me. The background is cluttered and detracts from the image. The model has possibilities though ... ;-)</td>', 'This is a little bit too "snapshot-like" for me. The background is cluttered and detracts from the image. The model has possibilities though ... ;-)', '2008-04-29 21:29:44.000000', NULL, 1),
(4665879, 671749, 73452, '<td valign="top">great find in a fun place, but the sun glares are annoying.  but it looks like it wasnt avoidable.</td>', 'great find in a fun place, but the sun glares are annoying.  but it looks like it wasnt avoidable.', '2008-04-29 21:30:25.000000', NULL, 1),
(4665883, 672178, 73452, '<td valign="top">AWWW!  an adorable puppy, and hey, i can even see you in her/his eyes!  good job on the focus too, right on the spot!</td>', 'AWWW!  an adorable puppy, and hey, i can even see you in her/his eyes!  good job on the focus too, right on the spot!', '2008-04-29 21:31:08.000000', NULL, 1),
